  function segmentBlockedBySmoke(from, to) {
    for (const c of clouds) {
      const cx = c.x;
      const cy = c.y;
      const cz = c.z;
      const dx = to.x - from.x;
      const dy = to.y - from.y;
      const dz = to.z - from.z;
      const lenSq = dx * dx + dy * dy + dz * dz;
      let t = 0;
      if (lenSq > 0) {
