    for (const p of projectiles) {
      p.alive = false;
      p.mesh.visible = false;
    }
    clouds.length = 0;
  }

  return {
    throw: throwGrenade,
    throwArc,
    step,
    clear,
    segmentBlockedBySmoke,
    get clouds() { return clouds; },
    get stats() { return { thrown, heDetonations, smokePops, clouds: clouds.length }; },
  };
