      retakeRole: null, // 'lead' | 'flank' — only while a charge is planted
      retakeAt: 0, // earliest time the flank retaker may move
      retakeSmoked: false,
      patrolAt: 0, patrolGoal: null,
      pushAt: 0, // carrier only: earliest live time the carrier may push
